def transform(grid):
    R=len(grid); C=len(grid[0])
    seen=[[False]*C for _ in range(R)]
    best=[]
    for i in range(R):
        for j in range(C):
            if grid[i][j]!=0 and not seen[i][j]:
                comp=[]; st=[(i,j)]; seen[i][j]=True
                while st:
                    x,y=st.pop(); comp.append((x,y))
                    for dx in (-1,0,1):
                        for dy in (-1,0,1):
                            if dx==0 and dy==0: continue
                            nx,ny=x+dx,y+dy
                            if 0<=nx<R and 0<=ny<C and not seen[nx][ny] and grid[nx][ny]!=0:
                                seen[nx][ny]=True; st.append((nx,ny))
                if len(comp)>len(best): best=comp
    if not best: return []
    col=grid[best[0][0]][best[0][1]]
    cs=set(best)
    cells=[(i,j) for i,r in enumerate(grid) for j,v in enumerate(r) if v==col]
    r0=min(c[0] for c in cells); r1=max(c[0] for c in cells)
    c0=min(c[1] for c in cells); c1=max(c[1] for c in cells)
    return [[col if (i,j) in cs else 0 for j in range(c0,c1+1)] for i in range(r0,r1+1)]
